from decimal import Decimal
from typing import Any


def _numeric(value: Any) -> Decimal:
    """Return legacy NVL-compatible numeric value, treating blank/missing as zero."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, bool):
        return Decimal(int(value))
    return Decimal(str(value).strip() or "0")


def _account_sort_key(account: dict) -> tuple[int, Any]:
    """Provide deterministic ascending primary-key ordering for common key types."""
    account_id = account.get("ACCT_ID", "")
    if isinstance(account_id, (int, float, Decimal)) and not isinstance(account_id, bool):
        return (0, _numeric(account_id))
    return (1, str(account_id))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """
    Apply the Meridian CRM credit-hold sweep without mutating input rows.

    Accounts are returned in input order; processing and audit emission follow
    ascending ACCT_ID order for eligible live customer accounts.
    """
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    for index in sorted(range(len(new_accounts)), key=lambda i: _account_sort_key(new_accounts[i])):
        account = new_accounts[index]

        if account.get("DEL_FLG") == "Y" or account.get("ACCT_TYP") != "C":
            continue

        account_id = account.get("ACCT_ID")
        exposure = Decimal("0")

        for order in orders:
            if (
                order.get("ACCT_ID") == account_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _numeric(order.get("TOT_AMT"))

        credit_limit = _numeric(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        if exposure <= credit_limit * Decimal("8") / Decimal("10") and account.get("CRED_HOLD") == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
